const webhook = $('Twilio Webhook').first().json;
const bodyRaw = String(webhook.Body || webhook.body || '').trim();
const data = $input.first().json;

function norm(s) {
  return String(s || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function escapeXml(s) {
  return String(s)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

const t = norm(bodyRaw);
const quiereInfo = !bodyRaw || /corte|agua|dengue|tanque|interagua|sector|aviso|info|hola|menu|ayuda/.test(t);

let reply;
if (!quiereInfo) {
  reply =
    'ZANKU — Aviso a la ciudadanía. Escriba *cortes*, *agua* o *info* para consultar anuncios de cortes Interagua e indicaciones preventivas. Este comunicado no promete reducción de dengue.';
} else if (!data || data.ok === false) {
  reply =
    'ZANKU: no fue posible consultar los cortes en este momento. Intente más tarde.';
} else {
  const lineas = [
    'ZANKU — Aviso a la ciudadanía',
    'Información de cortes de agua e indicaciones preventivas. No constituye diagnóstico ni promesa de reducción de dengue.',
    '',
  ];

  const cortes = Array.isArray(data.cortes_recientes) ? data.cortes_recientes : [];
  if (cortes.length === 0) {
    lineas.push('Sin cortes recientes en la base.');
  } else {
    lineas.push('Cortes recientes:');
    for (const c of cortes.slice(0, 5)) {
      const sector = c.sector || 'sector';
      const dur = c.duracion_horas ? ' · ' + c.duracion_horas : '';
      lineas.push('• ' + sector + ': ' + c.fecha_inicio + dur);
    }
  }

  const cola = Array.isArray(data.cola_regla_a) ? data.cola_regla_a : [];
  if (cola.length > 0) {
    lineas.push('');
    lineas.push('Prioridad operativa (Regla A):');
    for (const q of cola.slice(0, 4)) {
      const sector = q.sector || 'sector';
      const accion = q.accion || 'revisar recipientes';
      const just = q.justificacion ? ' — ' + q.justificacion : '';
      lineas.push('• ' + sector + ': ' + accion + just);
    }
  }

  lineas.push('');
  lineas.push('Recomendación sanitaria: cubra tanques, barriles y baldes con agua almacenada; elimine recipientes que acumulen agua.');
  lineas.push('Este comunicado es informativo; no garantiza prevenir casos de dengue.');
  reply = lineas.join('\n').slice(0, 1500);
}

const twiml =
  '<?xml version="1.0" encoding="UTF-8"?><Response><Message>' +
  escapeXml(reply) +
  '</Message></Response>';

return [{ json: { reply, twiml } }];
